12	/**
13	 * An invoice raised against a project: the id of the {@link Project} it belongs to and a money
14	 * amount. Mapped to the {@code invoice} table created by {@code V4__invoices.sql}. IDENTITY id so
15	 * the DB assigns it on insert (seed inserts explicit ids via JdbcTemplate; GENERATED BY DEFAULT
16	 * allows both).
17	 */
18	@Entity
19	@Table(name = "invoice")
20	public class Invoice {
