1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.HashMap;
5	import java.util.List;
6	import java.util.Map;
7	import java.util.Set;
8	import java.util.stream.Collectors;
9	import net.officefloor.web.HttpQueryParameter;
10	import net.officefloor.web.ObjectResponse;
11	
12	/**
13	 * {@code GET /api/clients/statement?clientId=N} — one client's statement: all of that client's
14	 * invoices in one place (every invoice raised against any of the client's projects, oldest first),
15	 * each carrying its derived {@code amountDue}, plus the {@code outstanding} total the client still
16	 * owes. Wired by {@code officefloor/rest/api/clients/statement.GET.yml}.
17	 *
18	 * <p>Invoices belong to projects, and projects belong to clients, so the client's invoices are
19	 * those whose project belongs to the client. Each invoice's amount due is its amount minus every
20	 * payment recorded against it (the same derivation {@link InvoicesGet} makes), and the outstanding
21	 * total is the sum of those amounts due — a server-derived aggregate, mirroring the dashboard's
22	 * outstanding total.
23	 */
24	public class ClientStatementGet {
25	
26	    public void service(@HttpQueryParameter("clientId") String clientId, ProjectRepository projects,
27	            InvoiceRepository invoices, PaymentRepository payments,
28	            ObjectResponse<StatementView> response) {
29	        Long id = Long.valueOf(clientId.trim());
30	
31	        // The client's projects: their ids are what ties an invoice back to this client.
32	        Set<Long> projectIds = projects.findAllByOrderByIdAsc().stream()
33	                .filter(p -> id.equals(p.getClientId()))
34	                .map(Project::getId)
35	                .collect(Collectors.toSet());
36	
37	        // Sum the payments per invoice once, so each invoice's amount due (amount less what has been
38	        // paid) can be worked out without re-scanning the payments per row.
39	        Map<Long, BigDecimal> paidByInvoice = new HashMap<>();
40	        for (Payment payment : payments.findAllByOrderByIdAsc()) {
41	            paidByInvoice.merge(payment.getInvoiceId(), payment.getAmount(), BigDecimal::add);
42	        }
43	
44	        List<Invoice> clientInvoices = invoices.findAllByOrderByIdAsc().stream()
45	                .filter(i -> projectIds.contains(i.getProjectId()))
46	                .collect(Collectors.toList());
47	
48	        BigDecimal outstanding = BigDecimal.ZERO;
49	        for (Invoice invoice : clientInvoices) {
50	            BigDecimal paid = paidByInvoice.getOrDefault(invoice.getId(), BigDecimal.ZERO);
51	            BigDecimal due = invoice.getAmount().subtract(paid);
52	            invoice.setAmountDue(due);
53	            outstanding = outstanding.add(due);
54	        }
55	
56	        response.send(new StatementView(clientInvoices, outstanding));
57	    }
58	}
