import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { InvoiceRowCells } from '../../slots/defs/invoiceRowCells';
import { money } from '../../ui/money';
import type { Invoice } from './InvoicesPanel';

// The "amount still due" cell of an invoice row — its own file, filling the invoice-row-cells slot.
// The panel is not edited to know how the due amount is worked out: this cell queries for itself
// (['invoices'], the SAME key the panel owns) and reads the invoice's server-derived amountDue (its
// amount minus every payment recorded against it), so it stays in step whenever a payment changes
// and the list is invalidated. Carries data-testid="invoice-due-amount" (the test contract).
export const contribution = InvoiceRowCells.fill({
  order: 10,
  Component: ({ invoiceId }: { invoiceId: number }) => {
    const invoices = useQuery({
      queryKey: ['invoices'],
      queryFn: () => getJson<Invoice[]>('/api/invoices'),
    });
    const invoice = (invoices.data ?? []).find((i) => i.id === invoiceId);
    const due = invoice ? Number(invoice.amountDue) : 0;
    return <td data-testid="invoice-due-amount">{money(due)}</td>;
  },
});

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

/**
 * Data access for {@link Invoice}. A Spring Data bean, injected into the OfficeFloor logic classes
 * that back the /api/invoices routes.
 */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** All invoices, oldest first, so the list order is stable for the UI and tests. */
    List<Invoice> findAllByOrderByIdAsc();

    /**
     * Every invoice at one lifecycle stage, oldest first, backing the all-invoices status filter.
     * The stable oldest-first order matches {@link #findAllByOrderByIdAsc()} so filtering only
     * narrows the list, never reorders it.
     */
    List<Invoice> findByStatusOrderByIdAsc(String status);

    /**
     * One page of invoices at one lifecycle stage, ordered by the supplied {@link Pageable} (the
     * all-invoices list orders by id ascending). Backs the all-invoices list's next/previous paging
     * when a status filter is active — only the requested slice is fetched, so a huge list is shown a
     * page at a time rather than all at once.
     */
    Page<Invoice> findByStatus(String status, Pageable pageable);

    /**
     * All invoices, earliest due date first (id as a stable tiebreaker), backing the project
     * invoices' sort-by-due-date control.
     */
    List<Invoice> findAllByOrderByDueDateAscIdAsc();

    /**
     * The money still owed: the sum of every SENT invoice's amount, or 0 when none are sent. Only
     * invoices that have actually been sent count — a DRAFT has not gone out yet, and a PAID one has
     * already been settled — so both are excluded. Backs the dashboard's outstanding total
     * ({@code GET /api/dashboard}).
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = 'SENT'")
    BigDecimal sumSentAmount();

    /**
     * How many SENT invoices are overdue as of {@code asOf}: an invoice whose due date has already
     * passed and which has actually gone out. Only SENT counts — a DRAFT has not been sent and a PAID
     * one is settled — and "overdue" means the due date is strictly before the reference day. Due
     * dates are ISO date literals (YYYY-MM-DD), which sort lexically = chronologically, so a string
     * comparison is the date comparison. Backs the dashboard's overdue count ({@code
     * GET /api/dashboard}).
     */
    @Query("SELECT COUNT(i) FROM Invoice i WHERE i.status = 'SENT' "
            + "AND i.dueDate IS NOT NULL AND i.dueDate < :asOf")
    long countSentOverdue(@Param("asOf") String asOf);

    /**
     * The total invoiced against one project: the sum of every invoice's amount raised against it, or
     * 0 when it has none. Backs the project budget panel's "invoiced" figure ({@code
     * GET /api/projects/budget}).
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.projectId = :projectId")
    BigDecimal sumAmountByProjectId(@Param("projectId") Long projectId);
}

